// Prompt assembler: roles assigned by stability (runs in your project)
function buildMessages({ systemRules, task, input }) {
  return [
    { role: "system", content: systemRules.join("\n") },
    // user turn carries the varying task + data, delimited explicitly:
    { role: "user", content: `${task}\n\n--- INPUT ---\n${input}` },
  ];
}
// Delimiters (--- INPUT ---) separate instruction from data: Ch.6 explains why.

