function buildMessages(parts) {
  return [
    { role: 'system', content: parts.systemRules.join('\n') },
    { role: 'user', content: parts.task + '\n\n--- INPUT ---\n' + parts.input },
  ];
}
const msgs = buildMessages({
  systemRules: ['You triage for an online shoe store.', 'Answer with JSON only.'],
  task: 'Classify into one of [billing, shipping, returns].',
  input: "My sneakers haven't arrived.",
});
console.log(msgs.length);
console.log(msgs[0].role + ': ' + msgs[0].content.split('\n').length + ' rules');
console.log(msgs[1].role + ' has delimiter: ' + msgs[1].content.includes('--- INPUT ---'));
console.log(JSON.stringify(msgs.map((m) => m.role)));

